  var SEL = 'i[class*="fa-"]';

  var css = document.createElement('style');
  css.textContent =
    'i[data-ri]{display:inline-flex;align-items:center;justify-content:center;font-style:normal;vertical-align:-0.15em;}' +
    'i[data-ri]::before,i[data-ri]::after{content:none!important;}' +
    'i[data-ri]>svg.ri-glyph{display:block;flex:none;}';
  document.head.appendChild(css);

  function lookup(el) {
    if (el.classList.contains('fa-brands')) return null;
    if (el.classList.contains('fa-copy-done')) return MAP['copy-done'];   // set by flash() in render.js after a copy
    for (var i = 0; i < el.classList.length; i++) {
      var c = el.classList[i];
      if (c.indexOf('fa-') === 0 && MAP[c.slice(3)]) return MAP[c.slice(3)];
    }
    return null;
  }

  function apply(el) {
    var old = el.querySelector(':scope > svg.ri-glyph');
    var name = lookup(el);
    if (!name) {                                   // not mapped: show the Font Awesome glyph as before
      if (old) old.remove();
      el.removeAttribute('data-ri');
      return;
    }
    if (old && old.getAttribute('data-name') === name) return;
    if (old) old.remove();
    var size = Math.round(parseFloat(getComputedStyle(el).fontSize)) || 18;
    el.insertAdjacentHTML('beforeend',
      '<svg class="ri-glyph" data-name="' + name + '" xmlns="http://www.w3.org/2000/svg" width="' + size +
      '" height="' + size + '" viewBox="0 0 24 24" fill="none" aria-hidden="true">' + ICONS[name] + '</svg>');
    el.setAttribute('data-ri', '');
  }

  function scan(root) {
    if (root.nodeType !== 1) return;
    if (root.matches(SEL)) apply(root);
    root.querySelectorAll(SEL).forEach(apply);
  }

  new MutationObserver(function (muts) {
    for (var i = 0; i < muts.length; i++) {
      var m = muts[i];
      if (m.type === 'attributes') { if (m.target.tagName === 'I') apply(m.target); }
      else m.addedNodes.forEach(scan);
    }
  }).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });

  function init() { scan(document.body); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
